// Enrich each lead against the lead database by domain
const enriched = [];
let enrichedCount = 0;
let needsResearch = 0;

for (const lead of $input.all()) {
  const domain = lead.json.domain;
  const enrichment = $mockClients.leadDatabase.enrich(domain);

  if (enrichment) {
    enriched.push({
      ...enrichment,
      contact_name: lead.json.contact_name,
      email: lead.json.email,
      enrichment_status: 'enriched'
    });
    enrichedCount++;
  } else {
    enriched.push({
      domain,
      contact_name: lead.json.contact_name,
      email: lead.json.email,
      enrichment_status: 'needs_research'
    });
    needsResearch++;
  }
}

return enriched.map(item => ({ json: item }));

// Update CRM with enriched leads
const crmRecords = $input.all()
  .filter(item => item.json.enrichment_status === 'enriched')
  .map(item => ({
    email: item.json.email,
    company: item.json.company,
    industry: item.json.industry,
    contact_role: item.json.contact_role
  }));

return crmRecords.map(r => ({ json: r }));

// Route needs_research leads to manual research queue
const needsResearch = $input.all()
  .filter(item => item.json.enrichment_status === 'needs_research')
  .map(item => item.json);

return needsResearch.map(r => ({ json: r }));

// Generate summary
const enrichedLeads = $input.all();
return [{
  json: {
    enriched_leads: enrichedLeads,
    total: enrichedLeads.length,
    enriched: enrichedLeads.filter(l => l.json.enrichment_status === 'enriched').length,
    needs_research: enrichedLeads.filter(l => l.json.enrichment_status === 'needs_research').length
  }
}];
